 16	export function activate(context: vscode.ExtensionContext) {
 17	  outputChannel = vscode.window.createOutputChannel("Consilium");
 18	
 19	  enableLogs("consilium-sdk:*");
 20	  setLogSink((...args: any[]) => {
 21	    handlerLog.log("SDK", { message: util.format(...args).replace(/\x1b\[[0-9;]*m/g, "") });
 22	
 23	    const message = util.format(...args).replace(/\x1b\[[0-9;]*m/g, "");
 24	    outputChannel.appendLine(message);
 25	  });
 26	  handlerLog.log("Consilium SDK logs enabled");
 27	
 28	  const remoteInfo = vscode.env.remoteName ? ` (remote: ${vscode.env.remoteName})` : "";
 29	  log(`Consilium extension activating...${remoteInfo}`);
 30	
 31	  initCLIManager(context);
 32	
 33	  // Remove title-generation temp sessions leaked by older builds.
 34	  cleanupStaleTitleSessions();
 35	
 36	  provider = new ConsiliumWebviewProvider(context.extensionUri, context.workspaceState, context.globalState, () => outputChannel.show());
 37	
 38	  // Initialize context state
 39	  updateLoginContext();
 40	
 41	  context.subscriptions.push(provider);
 42	  context.subscriptions.push(outputChannel);
 43	
 44	  context.subscriptions.push(
 45	    vscode.workspace.registerTextDocumentContentProvider("consilium-baseline", {
 46	      provideTextDocumentContent: async (uri: vscode.Uri) => {
 47	        const params = new URLSearchParams(uri.query);
 48	        const workDir = params.get("workDir");
 49	        const sessionId = params.get("sessionId");
 50	        if (!workDir || !sessionId) {
 51	          return "";
 52	        }
 53	
 54	        const relativePath = uri.path.slice(1);
 55	        const content = BaselineManager.getBaselineContent(workDir, sessionId, relativePath);
 56	        return content ?? "";
 57	      },
 58	    }),
 59	  );
 60	
 61	  context.subscriptions.push(
 62	    onSettingsChange((changedKeys) => {
 63	      provider.broadcast(Events.ExtensionConfigChanged, {
 64	        config: VSCodeSettings.getExtensionConfig(),
 65	        changedKeys,
 66	      });
 67	    }),
 68	  );
 69	
 70	  context.subscriptions.push(
 71	    vscode.window.registerWebviewViewProvider("consilium.webview", provider, {
 72	      webviewOptions: { retainContextWhenHidden: true },
 73	    }),
 74	  );
 75	
 76	  const commands: Record<string, () => void | Promise<void>> = {
 77	    "consilium.clearAllState": async () => {
 78	      await context.globalState.update("consilium.config", undefined);
 79	      await context.globalState.update("consilium.mcpServers", undefined);
 80	      await context.workspaceState.update("consilium.mcpEnabled", undefined);
 81	      vscode.window.showInformationMessage("Consilium: All state cleared!");
 82	    },
 83	    "consilium.openInTab": () => {
 84	      log("Opening Consilium in new tab");
 85	      provider.createPanel();
 86	    },
 87	    "consilium.openInSideBar": async () => {
 88	      log("Opening Consilium in side bar");
 89	      await vscode.commands.executeCommand("consilium.webview.focus");
 90	    },
 91	    "consilium.focusInput": async () => {
 92	      log("Focusing Consilium input");
 93	      await vscode.commands.executeCommand("consilium.webview.focus");
 94	      provider.broadcast(Events.FocusInput, {});
 95	    },
 96	    "consilium.insertMention": async () => {
 97	      const editor = vscode.window.activeTextEditor;
 98	      if (!editor) {
 99	        vscode.window.showWarningMessage("No active editor");
100	        return;
101	      }
102	      const document = editor.document;
103	      const selection = editor.selection;
104	      const relativePath = vscode.workspace.asRelativePath(document.uri);
105	
106	      let mention: string;
107	      if (selection.isEmpty) {
108	        mention = `@${relativePath}`;
109	      } else {
110	        const startLine = selection.start.line + 1;
111	        const endLine = selection.end.line + 1;
112	        mention = startLine === endLine ? `@${relativePath}:${startLine}` : `@${relativePath}:${startLine}-${endLine}`;
113	      }
114	
115	      log(`Inserting mention: ${mention}`);
116	      await vscode.commands.executeCommand("consilium.webview.focus");
117	      provider.broadcast(Events.InsertMention, { mention });
118	    },
119	    "consilium.newConversation": async () => {
120	      log("Starting new conversation");
121	      await vscode.commands.executeCommand("consilium.webview.focus");
122	      provider.broadcast(Events.NewConversation, {});
123	    },
124	    "consilium.showLogs": () => {
125	      outputChannel.show();
126	    },
127	    "consilium.dumpDebugLogs": () => {
128	      dumpLogsToOutputChannel();
129	    },
130	    "consilium.clearDebugLogs": () => {
131	      import("./utils/logger.js").then(({ clearLogs }) => clearLogs());
132	    },
133	    "consilium.resetConsilium": async () => {
134	      log("Resetting Consilium");
135	      provider.reloadAllWebviews();
136	    },
137	    "consilium.logout": async () => {
138	      log("Logout requested via command palette");
139	      await vscode.commands.executeCommand("consilium.webview.focus");
140	      vscode.window.showInformationMessage("Please use the logout button in Consilium settings.");
141	    },
142	  };
143	
144	  for (const [id, handler] of Object.entries(commands)) {
145	    context.subscriptions.push(vscode.commands.registerCommand(id, handler));
146	  }
147	
148	  log("Consilium extension activated");
149	}
