10	const checkWorkspace: Handler<void, WorkspaceStatus> = async (_, ctx) => {
11	  return {
12	    hasWorkspace: ctx.workDir !== null,
13	    path: ctx.workDir ?? undefined,
14	    workspaceRoot: ctx.workspaceRoot ?? undefined,
