23	const runCLI: Handler<{ args?: string[] }, { ok: boolean }> = async ({ args }) => {
24	  const cliPath = getCLIManager().getExecutablePath();
25	  const terminal = vscode.window.createTerminal({ name: "Consilium" });
26	  terminal.show();
27	  // Build command with quoted path and escaped args
28	  const quotedPath = `"${cliPath}"`;
29	
30	  // Safe-guard args with spaces or special characters
31	  // If arg contains spaces or quotes, wrap it in double quotes and escape existing double quotes
32	  const safeArgs = (args || []).map((arg) => (/[\s"']/.test(arg) ? `"${arg.replace(/"/g, '\\"')}"` : arg));
