331	  private async getOrCreateSession(webviewId: string, model: string, thinking: boolean, sessionId?: string, mode?: 'think' | 'do'): Promise<Session> {
332	    const workDir = this.requireWorkDir(webviewId);
333	    const cli = getCLIManager();
334	    const config = parseConfig();
335	
336	    // Determine actual thinking state based on model capability
337	    const modelConfig = getModelById(config.models, model);
338	    const thinkingMode = modelConfig ? getModelThinkingMode(modelConfig) : "none";
339	
340	    let actualThinking: boolean;
341	    if (thinkingMode === "always") {
342	      actualThinking = true;
343	    } else if (thinkingMode === "none") {
344	      actualThinking = false;
345	    } else {
346	      actualThinking = thinking;
347	    }
348	
349	    const executable = cli.getExecutablePath();
350	    const env = VSCodeSettings.environmentVariables;
351	    const globalYoloMode = VSCodeSettings.yoloMode;
352	    const requestedMode = mode ?? 'think';
353	    const actualDoMode = requestedMode === 'do';
354	    const actualYoloMode = actualDoMode ? true : globalYoloMode;
355	    const generationConfig = VSCodeSettings.generationConfig;
356	
357	    const key = requestedMode === 'do' ? `${webviewId}:do` : webviewId;
358	    const agentFile = resolveAgentFile(requestedMode, this.workspaceRoot, this.extensionRoot);
359	    const subagentSystemPrompts = resolveSubagentRoleOverrides(this.workspaceRoot, this.extensionRoot);
360	    sessionLog.log("getOrCreateSession", { webviewId, requestedSessionId: sessionId, existingKey: key, model, yoloMode: actualYoloMode, doMode: actualDoMode, agentFile: agentFile ?? '<default>' });
361	    const existing = this.sessions.get(key);
362	
363	    // Guard against silently converting an existing session from one mode to another.
364	    // This prevents a Do session loaded into the Think tab from being overwritten.
365	    if (existing && sessionId && sessionId === existing.sessionId && existing.doMode !== actualDoMode) {
366	      throw new Error(
367	        `Session ${sessionId} is a ${existing.doMode ? 'Do' : 'Think'} session. ` +
368	        `Switch to the ${existing.doMode ? 'Do' : 'Think'} tab before continuing.`
369	      );
370	    }
371	
372	    // Check if we need to restart the session
373	    if (existing) {
374	      const needsRestart =
375	        (sessionId && sessionId !== existing.sessionId) ||
376	        model !== existing.model ||
377	        actualThinking !== existing.thinking ||
378	        actualYoloMode !== existing.yoloMode ||
379	        actualDoMode !== existing.doMode ||
380	        executable !== existing.executable ||
381	        JSON.stringify(env) !== JSON.stringify(existing.env) ||
382	        JSON.stringify(generationConfig) !== JSON.stringify((existing as any)._generationOverrides);
383	
384	      if (needsRestart) {
385	        await safeCloseSession(existing, key);
386	        this.sessions.delete(key);
387	        this.turns.delete(key);
388	      }
389	    }
390	
391	    const current = this.sessions.get(key);
392	    if (current) {
393	      return current;
394	    }
395	
396	    const session = createSession({
397	      workDir,
398	      model,
399	      thinking: actualThinking,
400	      yoloMode: actualYoloMode,
401	      doMode: actualDoMode,
402	      sessionId,
403	      executable,
404	      env,
405	      agentFile,
406	      subagentSystemPrompts,
407	      clientInfo: { name: "consilium-code-for-vs-code", version: VSCodeSettings.getExtensionConfig().version },
408	      generationOverrides: generationConfig.temperature !== undefined || generationConfig.topP !== undefined || generationConfig.maxTokens !== undefined
409	        ? generationConfig
410	        : undefined,
411	    });
412	
413	    this.sessions.set(key, session);
414	    this.fileManager.setSessionId(key, session.sessionId);
415	    this.persistTabState(webviewId);
416	    return session;
417	  }
418	
419	  async disposeView(webviewId: string): Promise<void> {
420	    // Close think session
421	    const thinkSession = this.sessions.get(webviewId);
422	    if (thinkSession) {
423	      await safeCloseSession(thinkSession, webviewId);
424	      this.sessions.delete(webviewId);
425	      this.turns.delete(webviewId);
426	    }
427	    this.fileManager.disposeView(webviewId);
428	
429	    // Close do session
430	    const doKey = `${webviewId}:do`;
431	    const doSession = this.sessions.get(doKey);
432	    if (doSession) {
433	      await safeCloseSession(doSession, doKey);
434	      this.sessions.delete(doKey);
435	      this.turns.delete(doKey);
436	    }
437	    this.fileManager.disposeView(doKey);
438	
439	    // Clear active tab
440	    this.activeTabs.delete(webviewId);
441	  }
442	
443	  async dispose(): Promise<void> {
444	    this.fileManager.dispose();
445	    for (const s of this.sessions.values()) {
446	      await s.close();
447	    }
448	    this.sessions.clear();
449	    this.turns.clear();
450	  }
451	}

