 12	import { bridge, Events } from "./services";
 13	import { useAppInit } from "./hooks/useAppInit";
 14	import { isPreflightError } from "shared/errors";
 15	import type { UIStreamEvent, StreamError, ExtensionConfig } from "shared/types";
 16	import "./styles/index.css";
 17	
 18	function MainContent({ onAuthAction }: { onAuthAction: () => void }) {
 19	  const { processEvent, startNewConversation, sessionId, setTitle } = useChatStore();
 20	  const { setMCPServers, setExtensionConfig, extensionConfig } = useSettingsStore();
 21	
 22	  useEffect(() => {
 23	    // Batch events via requestAnimationFrame to prevent main thread saturation
 24	    // during high-frequency streams (thinking tokens, tool call parts).
 25	    let pendingEvents: UIStreamEvent[] = [];
 26	    let flushScheduled = false;
 27	
 28	    const flush = () => {
 29	      flushScheduled = false;
 30	      const batch = pendingEvents;
 31	      pendingEvents = [];
 32	      if (batch.length === 0) return;
 33	
 34	      // Process all buffered events in a single state update
 35	      for (const event of batch) {
 36	        processEvent(event);
 37	      }
 38	
 39	      // Handle errors from the batch
 40	      for (const event of batch) {
 41	        if (event.type === "error") {
 42	          const streamError = event as StreamError;
 43	          if (isPreflightError(streamError.code || "UNKNOWN")) {
 44	            toast.error(streamError.message);
 45	          }
 46	        }
 47	      }
 48	    };
 49	
 50	    const scheduleFlush = () => {
 51	      if (flushScheduled) return;
 52	      flushScheduled = true;
 53	      if (typeof requestAnimationFrame !== "undefined") {
 54	        requestAnimationFrame(flush);
 55	      } else {
 56	        setTimeout(flush, 0);
 57	      }
 58	    };
 59	
 60	    return bridge.on(Events.StreamEvent, (event: UIStreamEvent) => {
 61	      // 只有当前已有 session 时才过滤，确保 session_start 能正常处理
 62	      if (sessionId && "_sessionId" in event && event._sessionId && event._sessionId !== sessionId) {
 63	        console.log("Ignored stream event from another session:", event._sessionId);
 64	        return;
 65	      }
 66	      pendingEvents.push(event);
 67	      scheduleFlush();
 68	    });
 69	  }, [processEvent, sessionId]);
 70	
 71	  useEffect(() => {
 72	    const unsubs = [
 73	      bridge.on(Events.MCPServersChanged, setMCPServers),
 74	      bridge.on(Events.ExtensionConfigChanged, ({ config }: { config: ExtensionConfig }) => setExtensionConfig(config)),
 75	      bridge.on(Events.FocusInput, () => document.querySelector<HTMLTextAreaElement>("textarea")?.focus()),
 76	      bridge.on(Events.NewConversation, () => startNewConversation()),
 77	      bridge.on(Events.SessionTitleUpdated, ({ sessionId: updatedSessionId, title, source }: { sessionId: string; title: string; source: "user" | "llm" | "fallback" }) => {
 78	        setTitle(updatedSessionId, title, source);
 79	      }),
 80	    ];
 81	    return () => unsubs.forEach((u) => u());
 82	  }, [setMCPServers, setExtensionConfig, startNewConversation, setTitle]);
 83	
 84	  useEffect(() => {
 85	    useChatStore.getState().initTabs();
 86	  }, []);
 87	
 88	  useEffect(() => {
 89	    if (!extensionConfig.enableNewConversationShortcut) return;
 90	    const handler = (e: KeyboardEvent) => {
 91	      if ((e.metaKey || e.ctrlKey) && e.key === "n") {
 92	        e.preventDefault();
 93	        startNewConversation();
 94	      }
 95	    };
 96	    window.addEventListener("keydown", handler);
 97	    return () => window.removeEventListener("keydown", handler);
 98	  }, [extensionConfig.enableNewConversationShortcut, startNewConversation]);
 99	
100	  return (
101	    <>
102	      <div className="flex-1 min-h-0 relative group/chat">
103	        <ChatArea />
104	      </div>
105	      <div className="shrink-0 max-h-[80vh] flex flex-col min-h-0">
106	        <InputArea onAuthAction={onAuthAction} />
107	      </div>
108	      <MCPServersModal />
109	      <WorkDirModal />
110	    </>
111	  );
112	}
