105	export function useWelcomeHint(): WelcomeHint {
106	  const [hasAgentMd, setHasAgentMd] = useState<boolean | null>(null);
107	  const [hasHistory, setHasHistory] = useState<boolean | null>(null);
108	
109	  useEffect(() => {
110	    bridge
111	      .checkFileExists("AGENT.md")
112	      .then(setHasAgentMd)
113	      .catch(() => setHasAgentMd(false));
114	    bridge
115	      .getConsiliumSessions()
116	      .then((s) => setHasHistory(s.length > 0))
117	      .catch(() => setHasHistory(false));
118	  }, []);
119	
120	  return useMemo(() => {
121	    // First time user: show shortcut guide
122	    if (hasHistory === false) {
123	      return HINT_FIRST_TIME;
124	    }
125	    // 30% chance to show AGENT.md hint if missing
126	    if (hasAgentMd === false && withProbability(0.3)) {
127	      return HINT_AGENT_MD;
128	    }
129	    return pickRandom(HINTS_POOL);
130	  }, [hasAgentMd, hasHistory]);
131	}

