135	  [Methods.GetConsiliumSessions]: async (_, ctx) => {
136	    if (!ctx.workDir) return [];
137	    const sessions = await listSessions(ctx.workDir);
138	    for (const s of sessions) {
139	      const meta = ctx.getSessionMetadata(s.id);
140	      s.brief = meta?.title || s.brief;
141	      (s as any).mode = meta?.mode || 'legacy';
