 89	/** Proxy the /models request through the extension host to bypass webview CSP. */
 90	function httpGet(url: string, headers: Record<string, string>): Promise<string> {
 91	  return new Promise((resolve, reject) => {
 92	    const parsed = new URL(url);
 93	    const lib = parsed.protocol === "https:" ? https : http;
 94	    const req = lib.request(
 95	      { hostname: parsed.hostname, path: parsed.pathname + parsed.search, port: parsed.port || undefined, headers },
 96	      (res) => {
 97	        let body = "";
 98	        res.on("data", (chunk) => (body += chunk));
 99	        res.on("end", () => {
100	          if (res.statusCode && res.statusCode >= 400) {
101	            reject(new Error(`HTTP ${res.statusCode}: ${body.slice(0, 200)}`));
102	          } else {
103	            resolve(body);
104	          }
105	        });
106	      },
107	    );
108	    req.on("error", reject);
109	    req.end();
110	  });
111	}
