116	const fetchProviderModels: Handler<FetchModelsParams, ModelEntry[]> = async ({ baseUrl, apiKey }) => {
117	  const url = baseUrl.replace(/\/$/, "") + "/models";
118	  const body = await httpGet(url, { Authorization: `Bearer ${apiKey}`, Accept: "application/json" });
119	  const data = JSON.parse(body);
120	  const list: ModelEntry[] = Array.isArray(data) ? data : (data.data ?? []);
121	  return list
122	    .map((m: any) => ({ id: m.id, name: m.name || m.id, context_length: m.context_length, pricing: m.pricing }))
123	    .sort((a: ModelEntry, b: ModelEntry) => a.id.localeCompare(b.id));
124	};
