  9	export function WorkDirModal() {
 10	  const { workDirModalOpen, setWorkDirModalOpen, currentWorkDir, workspaceRoot, setCurrentWorkDir } = useSettingsStore();
 11	  const { startNewConversation } = useChatStore();
 12	  const [workDirs, setWorkDirs] = useState<string[]>([]);
 13	  const [loading, setLoading] = useState(false);
 14	
 15	  useEffect(() => {
 16	    if (workDirModalOpen) {
 17	      bridge.getRegisteredWorkDirs().then(setWorkDirs);
 18	    }
 19	  }, [workDirModalOpen]);
 20	
 21	  const handleSelect = async (dir: string | null) => {
 22	    setLoading(true);
 23	    try {
 24	      const result = await bridge.setWorkDir(dir);
 25	      if (result.ok) {
 26	        setCurrentWorkDir(result.workDir === workspaceRoot ? null : result.workDir);
 27	        await startNewConversation();
 28	        setWorkDirModalOpen(false);
 29	      }
 30	    } finally {
 31	      setLoading(false);
 32	    }
 33	  };
 34	
 35	  const handleBrowse = async () => {
 36	    setLoading(true);
 37	    try {
 38	      const result = await bridge.browseWorkDir();
 39	      if (result.ok && result.workDir) {
 40	        setCurrentWorkDir(result.workDir === workspaceRoot ? null : result.workDir);
 41	        await startNewConversation();
 42	        setWorkDirModalOpen(false);
 43	      }
 44	    } finally {
 45	      setLoading(false);
 46	    }
 47	  };
 48	
 49	  const displayPath = (fullPath: string) => {
 50	    if (!workspaceRoot) return fullPath;
 51	    if (fullPath === workspaceRoot) return fullPath.split("/").pop() || fullPath;
 52	    return fullPath.replace(workspaceRoot, ".");
 53	  };
 54	
 55	  const isSelected = (dir: string) => {
 56	    if (!currentWorkDir) return dir === workspaceRoot;
 57	    return dir === currentWorkDir;
 58	  };
 59	
 60	  return (
 61	    <Dialog open={workDirModalOpen} onOpenChange={setWorkDirModalOpen}>
 62	      <DialogContent className="sm:max-w-md">
 63	        <DialogHeader>
 64	          <DialogTitle>Select Working Directory</DialogTitle>
 65	        </DialogHeader>
 66	
 67	        <div className="space-y-1 max-h-64 overflow-y-auto -mx-1 px-1">
 68	          {workDirs.map((dir) => (
 69	            <button
 70	              key={dir}
 71	              onClick={() => handleSelect(dir === workspaceRoot ? null : dir)}
 72	              disabled={loading}
 73	              className={cn(
 74	                "w-full flex items-center gap-2 px-3 py-2 rounded-md text-left text-sm transition-colors",
 75	                isSelected(dir) ? "bg-accent" : "hover:bg-accent/50",
 76	                loading && "opacity-50 cursor-not-allowed",
 77	              )}
 78	            >
 79	              {dir === workspaceRoot ? (
 80	                <IconHome className="size-4 text-muted-foreground shrink-0" />
 81	              ) : (
 82	                <IconFolder className="size-4 text-muted-foreground shrink-0" />
 83	              )}
 84	              <span className="flex-1 truncate">{displayPath(dir)}</span>
 85	              {isSelected(dir) && <IconCheck className="size-4 text-blue-500 shrink-0" />}
 86	              {dir === workspaceRoot && <span className="text-xs text-muted-foreground">(root)</span>}
 87	            </button>
 88	          ))}
 89	        </div>
 90	
 91	        <DialogFooter className="sm:justify-between gap-2">
 92	          <div className="flex gap-2">
 93	            <Button variant="outline" size="sm" onClick={handleBrowse} disabled={loading}>
 94	              <IconFolderOpen className="size-4 mr-1.5" />
 95	              Browse...
 96	            </Button>
 97	            {currentWorkDir && (
 98	              <Button variant="outline" size="sm" onClick={() => handleSelect(null)} disabled={loading}>
 99	                <IconHome className="size-4 mr-1.5" />
100	                Reset
101	              </Button>
102	            )}
103	          </div>
104	          <Button variant="ghost" size="sm" onClick={() => setWorkDirModalOpen(false)}>
105	            Cancel
106	          </Button>
107	        </DialogFooter>
108	      </DialogContent>
109	    </Dialog>
110	  );
111	}

