 43	const IMAGE_EXTENSIONS = ["png", "jpg", "jpeg", "gif", "webp"];
 44	const VIDEO_EXTENSIONS = ["mp4", "webm", "mov"];
 45	
 46	const IMAGE_MIME_TYPES: Record<string, string> = {
 47	  ".png": "image/png",
 48	  ".jpg": "image/jpeg",
 49	  ".jpeg": "image/jpeg",
 50	  ".gif": "image/gif",
 51	  ".webp": "image/webp",
