 57	function toAbsolute(workDir: string, filePath: string): string {
 58	  return path.isAbsolute(filePath) ? filePath : path.join(workDir, filePath);
 59	}
 60	
 61	function isInsideWorkDir(workDir: string, absolutePath: string): boolean {
 62	  const rel = path.relative(workDir, absolutePath);
 63	  return !!rel && !rel.startsWith("..") && !path.isAbsolute(rel);
 64	}
