 66	function getMimeType(ext: string): string {
 67	  const mimeTypes: Record<string, string> = {
 68	    png: "image/png",
 69	    jpg: "image/jpeg",
 70	    jpeg: "image/jpeg",
 71	    gif: "image/gif",
 72	    webp: "image/webp",
 73	    mp4: "video/mp4",
 74	    webm: "video/webm",
 75	    mov: "video/quicktime",
 76	  };
 77	  return mimeTypes[ext] || "application/octet-stream";
 78	}
