117	const pickMedia: Handler<PickMediaParams, string[]> = async (params) => {
118	  const maxCount = params.maxCount ?? 9;
119	  const includeVideo = params.includeVideo ?? true;
120	
121	  const filters: Record<string, string[]> = {
122	    Images: IMAGE_EXTENSIONS,
123	  };
124	  if (includeVideo) {
125	    filters["Videos"] = VIDEO_EXTENSIONS;
126	    filters["All Media"] = [...IMAGE_EXTENSIONS, ...VIDEO_EXTENSIONS];
127	  }
128	
129	  const uris = await vscode.window.showOpenDialog({
130	    canSelectMany: true,
131	    filters,
132	    title: "Select Media",
133	  });
134	
135	  if (!uris) {
136	    return [];
137	  }
138	
139	  const results: string[] = [];
140	  const maxImageSize = 10 * 1024 * 1024;
141	  const maxVideoSize = 20 * 1024 * 1024;
142	
143	  for (const uri of uris.slice(0, maxCount)) {
144	    try {
145	      const ext = path.extname(uri.fsPath).toLowerCase().slice(1);
146	      const isVideo = VIDEO_EXTENSIONS.includes(ext);
147	      const maxSize = isVideo ? maxVideoSize : maxImageSize;
148	
149	      const stat = await vscode.workspace.fs.stat(uri);
150	      if (stat.size > maxSize) {
151	        continue;
152	      }
153	
154	      const data = await vscode.workspace.fs.readFile(uri);
155	      const mime = getMimeType(ext);
156	      results.push(`data:${mime};base64,${Buffer.from(data).toString("base64")}`);
157	    } catch {
158	      // skip
159	    }
160	  }
161	
162	  return results;
163	};
