167	  const absolutePath = toAbsolute(workDir, params.filePath);
168	  if (!isInsideWorkDir(workDir, absolutePath)) {
169	    return { ok: false };
170	  }
171	
172	  const uri = vscode.Uri.file(absolutePath);
173	  await vscode.commands.executeCommand("vscode.open", uri);
